insert into temp_tv_shows_seed (id, title, year, genre, creator, writers, cast_members, age_rating, overview, synopsis, poster_url, seasons, source_key)
values
  ('1146280141919539787', '¡Mucha Lucha!', 2002, 'Kids, Comedy, Animation', 'Eddie Mort, Lili Chin', null, 'Jason Marsden, Kimberly Brooks, Candi Milo', null, '¡Mucha Lucha! is an American-Canadian animated television series created by Eddie Mort and Lili Chin. The show is set in a town centered around lucha libre and follows the adventures of three children, Rikochet, The Flea and Buena Girl, as they struggle through the Foremost World-Renowned International School of Lucha, where they study.', '¡Mucha Lucha! is an American-Canadian animated television series created by Eddie Mort and Lili Chin. The show is set in a town centered around lucha libre and follows the adventures of three children, Rikochet, The Flea and Buena Girl, as they struggle through the Foremost World-Renowned International School of Lucha, where they study.', 'https://image.tmdb.org/t/p/w500/w12B6di7moo2otX4X4y3y3gKagz.jpg', 3, 'tmdb:tv:288'),
  ('167038692298573150', '¡Rob!', 2012, 'Comedy', 'Lew Morton, Rob Schneider', null, 'Eugenio Derbez, Rob Schneider, Claudia Bassols, Cheech Marin, Diana Maria Riva, Lupe Ontiveros', null, 'Rob is an American comedy television series that premiered on CBS on January 12, 2012, at 8:30 pm as a midseason replacement for Rules of Engagement, and ended on March 1, 2012. The series stars Rob Schneider alongside Cheech Marin, Claudia Bassols, Diana Maria Riva, Eugenio Derbez, Ricky Rico, and Lupe Ontiveros. The show was produced by Two and a Half Men''s The Tannenbaum Company and CBS Television Studios. On May 13, 2012, CBS canceled the series.', 'Rob is an American comedy television series that premiered on CBS on January 12, 2012, at 8:30 pm as a midseason replacement for Rules of Engagement, and ended on March 1, 2012. The series stars Rob Schneider alongside Cheech Marin, Claudia Bassols, Diana Maria Riva, Eugenio Derbez, Ricky Rico, and Lupe Ontiveros. The show was produced by Two and a Half Men''s The Tannenbaum Company and CBS Television Studios. On May 13, 2012, CBS canceled the series.', 'https://image.tmdb.org/t/p/w500/a8jlKhRSfmbfPYjehxY6KZIond3.jpg', 1, 'tmdb:tv:42014'),
  ('987614781743989159', '¡Vivan los niños!', 2002, 'Soap, Kids', 'Abel Santacruz', 'Kary Fajer', 'Andrea Legarreta, Eduardo Capetillo, Miguel de León, Alejandra Procuna, Joaquín Cordero, Ignacio López Tarso, Raquel Olmedo, Renata Flores', null, '¡Vivan los niños! is a Mexican telenovela for children that premiered in 2002. It ran for 155 episodes and finished in 2003. The opening, Vivan los niños, was recorded by the Latin pop group OV7. One of its closing themes, also entitled Vivan los niños, was performed by Cuban-American singer and songwriter Ana Cristina. The show is a version of the Argentinian telenovela "Jacinta Pichimahuida, la maestra que no se olvida". The series starred Andrea Legarreta as 2nd grade teacher Lupita Gómez. After the series ended, Andrea became the long-time host of the morning talk show Hoy. On July 12, 2012, in celebration of Andrea''s birthday, the producers of Hoy reunited her with the young actors who played her students on the series.', '¡Vivan los niños! is a Mexican telenovela for children that premiered in 2002. It ran for 155 episodes and finished in 2003. The opening, Vivan los niños, was recorded by the Latin pop group OV7. One of its closing themes, also entitled Vivan los niños, was performed by Cuban-American singer and songwriter Ana Cristina. The show is a version of the Argentinian telenovela "Jacinta Pichimahuida, la maestra que no se olvida". The series starred Andrea Legarreta as 2nd grade teacher Lupita Gómez. After the series ended, Andrea became the long-time host of the morning talk show Hoy. On July 12, 2012, in celebration of Andrea''s birthday, the producers of Hoy reunited her with the young actors who played her students on the series.', 'https://image.tmdb.org/t/p/w500/ksgIdxk9M5KPrOWZXLhjdrkrS2t.jpg', 1, 'tmdb:tv:19588'),
  ('426912168818763335', '¿A qué estás esperando?', 2024, 'Comedy', 'Natalia Durán', null, 'Rubén Cortada, Adriana Torrebejano, Francisco Ortiz, Eva Ugarte, Manuel Baqueiro, Llum Barrera, Mariano Llorente, Aria Bedmar', null, 'No description available yet.', 'No description available yet.', 'https://image.tmdb.org/t/p/w500/mj1oN9iRqqsX5PpVVCWsMPA2YP.jpg', 2, 'tmdb:tv:242865'),
  ('149808578750530805', '¿Dónde carajos está Umaña?', 2012, 'Comedy', null, null, 'Alejandra restrepo, Diego Trujillo, Marcela Carvajal, Carolina López, Erick Cuéllar, Ana María Kamper, Sergio Borrero', null, 'No description available yet.', 'No description available yet.', 'https://image.tmdb.org/t/p/w500/ihanTZIsgvW8HyWenjTEYFSNhvf.jpg', 1, 'tmdb:tv:123997'),
  ('1075131648337865179', '¿Dónde está Elisa?', 2009, 'Soap, Mystery, Drama', 'Pablo Illanes', null, 'Sigrid Alegría, Francisco Melo, Álvaro Rudolphy, Francisco Reyes, Paola Volpato, Alejandra Fosalba, Álvaro Morales, Andrés Velasco', null, 'A teenager''s disappearance causes her family''s world to turn upside down. In the police quest to find her, all her relatives will become suspects of her kidnapping.', 'A teenager''s disappearance causes her family''s world to turn upside down. In the police quest to find her, all her relatives will become suspects of her kidnapping.', 'https://image.tmdb.org/t/p/w500/muVJNZUhAcngtbGqPglyachX6Ea.jpg', 1, 'tmdb:tv:21667'),
