  ('1029063762431601149', 'Click Your Heart', 2016, 'Comedy', null, null, 'Kwon Min-a, Zuho, Kang Chan-hee, Rowoon, Lee Jae-yoon, Kim Seol-hyun, Lee Jung-shin, Park Jin-joo', null, 'Starring AOA''s Min Ah as an endearing outcast who turns the heads of Da Won, Ro Woon, Cha Ni and Ju Ho, this interactive choose-your-own-adventure series unites AOA and Neoz trainees in a sweet string of high school romances.', 'Starring AOA''s Min Ah as an endearing outcast who turns the heads of Da Won, Ro Woon, Cha Ni and Ju Ho, this interactive choose-your-own-adventure series unites AOA and Neoz trainees in a sweet string of high school romances.', 'https://image.tmdb.org/t/p/w500/GFZSMijXGpzHwqFxkk4cKVSjRb.jpg', 1, 'tmdb:tv:66020'),
  ('77191079894951876', 'Clickbait', 2021, 'Drama, Mystery, Crime', 'Christian White, Tony Ayres', null, 'Adrian Grenier, Zoe Kazan, Betty Gabriel, Phoenix Raei, Camaron Engels, Ian Meadows, Jaylin Fletcher, Jessica Collins', 'TV-MA', 'When family man Nick Brewer is abducted in a crime with a sinister online twist, those closest to him race to uncover who is behind it and why.', 'When family man Nick Brewer is abducted in a crime with a sinister online twist, those closest to him race to uncover who is behind it and why.', 'https://image.tmdb.org/t/p/w500/q42t4S113jebD1khigJt8z3m1mD.jpg', 1, 'tmdb:tv:129495'),
