  ('40661761016616578', 'Love Is a Poison', 2024, 'Drama, Mystery', 'Keisuke Makino', 'Izumi Kawasaki', 'Shogo Hama, Katsumi Hyodo, Kogaken, Aoba Kawai, Ikuji Nakamura, Nose Rin', 'TV-PG', 'An elite but socially awkward lawyer takes in a genius con artist. Together, they secretly solve complex legal cases using unethically obtained evidence.', 'An elite but socially awkward lawyer takes in a genius con artist. Together, they secretly solve complex legal cases using unethically obtained evidence.', 'https://image.tmdb.org/t/p/w500/9r01eZefgZrCOLLqDIeEFtLqpw2.jpg', 1, 'tmdb:tv:259881'),
  ('783216627322518641', 'Love Is Better the Second Time Around', 2024, 'Drama', null, null, 'Makoto Hasegawa, Robin Furuya, Aloha Takamatsu, Nose Rin, Haruki Mochizuki', null, 'Journalist Akihiro reunites with Takashi, his high school love, now a professor. Old emotions resurface as they navigate between professionalism and the past.', 'Journalist Akihiro reunites with Takashi, his high school love, now a professor. Old emotions resurface as they navigate between professionalism and the past.', 'https://image.tmdb.org/t/p/w500/vunLCiSVfeJpr82ft773bTKQdXs.jpg', 1, 'tmdb:tv:246482'),
