  ('436789743874429911', 'Nobody''s Boy: Remi', 1977, 'Animation, Drama', null, null, 'Masako Sugaya, Yōsuke Kondō, Hiroko Suzuki, Takeshi Aono, Reiko Mutoh, Yoshiko Yamamoto, Noriko Ohara, Shozo Iizuka', null, 'Orphaned Remi gets hired out to a traveling street entertainer Vitalis when her foster parents fall on hard times.', 'Orphaned Remi gets hired out to a traveling street entertainer Vitalis when her foster parents fall on hard times.', 'https://image.tmdb.org/t/p/w500/vWPWVexfLDWU9vszZJVKtcgyuiL.jpg', 1, 'tmdb:tv:44725'),
  ('127697625844751781', 'Nobody''s Looking', 2019, 'Comedy', 'Daniel Rezende, Carolina Markowicz, Teo Poppovic', null, 'Victor Lamoglia, Júlia Rabello, Danilo de Moura, Kéfera Buchmann, Leandro Ramos, Augusto Madeira, Telma Souza, Projota', 'TV-MA', 'A new guardian "angelus" uncovers a secret behind the Angelus System''s bureaucracy that leads him to break its official rules about protecting humans.', 'A new guardian "angelus" uncovers a secret behind the Angelus System''s bureaucracy that leads him to break its official rules about protecting humans.', 'https://image.tmdb.org/t/p/w500/xEOTiRPhStF2mgciX5Jbdz3lXEL.jpg', 1, 'tmdb:tv:95121'),
