  ('1010684516132449623', 'Sin novedad', 2021, 'Comedy, Crime', 'Álex Mendíbil, Rodrigo Sopeña', null, 'Arturo Valls, Carlos Areces, Pilar Castro, Adriana Torrebejano, Toni Acosta, Omar Banana', null, 'Two policemen waiting for the mission that will make them heroes. Two criminals waiting for the crime of their lives. Two inspectors waiting to get involved in the action. The night-time comedy that everyone’s been waiting for!', 'Two policemen waiting for the mission that will make them heroes. Two criminals waiting for the crime of their lives. Two inspectors waiting to get involved in the action. The night-time comedy that everyone’s been waiting for!', 'https://image.tmdb.org/t/p/w500/b0vNIhuDGSUk0pD0k8bYjWvvk5L.jpg', 1, 'tmdb:tv:130215'),
  ('614147978882195726', 'Sin senos sí hay paraíso', 2016, 'Action & Adventure, Crime, Drama, Mystery', 'Gustavo Bolívar', null, 'Carmen Villalobos, Carolina Gaitán, Kimberly Reyes, Fabián Ríos, Catherine Siachoque, Roberto Manrique, Juan Pablo Urrego, Francisco Bolívar', 'TV-MA', 'A young woman born in a mafia-controlled town seeks revenge on those who wrongfully harmed and imprisoned her family.', 'A young woman born in a mafia-controlled town seeks revenge on those who wrongfully harmed and imprisoned her family.', 'https://image.tmdb.org/t/p/w500/7lBJ6lOS0uQqsH13U9iMTikawQS.jpg', 4, 'tmdb:tv:67335'),
