  ('340371043190640341', 'Strong Woman Do Bong-Soon', 2017, 'Comedy, Action & Adventure, Drama', 'Baek Mi-kyoung', null, 'Park Bo-young, Park Hyung-sik, Kim Ji-soo, Jun Suk-ho, Shim Hye-jin, You Chea-myung, An Woo-yeon, Kim Min-kyo', 'TV-14', 'Born with supernatural strength, Bong-soon fights evil and procures justice while getting tangled in a love triangle with her CEO boss and cop crush.', 'Born with supernatural strength, Bong-soon fights evil and procures justice while getting tangled in a love triangle with her CEO boss and cop crush.', 'https://image.tmdb.org/t/p/w500/sPdS6oUdXfBNGKROE5RY5s5laqx.jpg', 1, 'tmdb:tv:68814'),
  ('36898830091127018', 'Strongest Deliveryman', 2017, 'Drama', 'Lee Jeong-woo', 'Lee Jeong-woo', 'Go Kyung-pyo, Chae Soo-bin, Kim Seon-ho, Go Won-hee, Nam Ji-hyun, Heo Ji-won, Kim Min-seok, Lee Kan-hee', null, 'Two gutsy food delivery workers strive to overcome their socioeconomic disadvantages to achieve big goals -- and bump into love along the way.', 'Two gutsy food delivery workers strive to overcome their socioeconomic disadvantages to achieve big goals -- and bump into love along the way.', 'https://image.tmdb.org/t/p/w500/okUxALg0RQarUiWOtS8iwq6CNOO.jpg', 1, 'tmdb:tv:72396'),
