  ('198932958425195547', 'Too Hot to Handle: Italy', 2025, 'Reality', null, null, 'Federico Palana, Jacopo Tommasini, Michelle Veronesi, Klodian Mihaj, Alessia Toso, Maurilio La Barbera, Ibiza Altea, Carlotta Cocins', 'TV-MA', 'A group of flirty singles mixes in paradise, but to win the cash prize, there''s a catch: no sex. Will they resist temptation or let desire take over?', 'A group of flirty singles mixes in paradise, but to win the cash prize, there''s a catch: no sex. Will they resist temptation or let desire take over?', 'https://image.tmdb.org/t/p/w500/8RoPqh5DT2fA4AErP49g1t17H40.jpg', 1, 'tmdb:tv:286867'),
  ('755295655300725137', 'Too Hot to Handle: Latino', 2021, 'Reality', 'Charlie Bennett, Laura Gibson', null, 'Itatí Cantoral, Caro Mendoza, Manuela Angel, Zaira de la Morena, Lilian Dg, Clovis Nienow, Flor Zaccanti, Israel Lomeli', null, 'Singles from Latin America and Spain are challenged to give up sex. But here, abstinence comes with a silver lining: US$100,000.', 'Singles from Latin America and Spain are challenged to give up sex. But here, abstinence comes with a silver lining: US$100,000.', 'https://image.tmdb.org/t/p/w500/tnW1J8sg0W8WiL9083tSW6K0yL3.jpg', 1, 'tmdb:tv:131589'),
